def trans(x, k, n, name):
    z = np.sign(x) * abs(x) ** n
    if name == 'tanh':
        return np.tanh(k * z)
    if name == 'rat':
        return z / (1 + k * z * z)
    if name == 'hyp':
        return z / np.sqrt(1 + k * z * z)
    if name == 'soft':
        return z / (1 + k * abs(z))
    if name == 'atan':
        return np.arctan(k * z)
    if name == 'exp':
        return z * np.exp(-k * z * z)
    if name == 'sinh':
        return np.arcsinh(k * z)
    if name == 'direct':
        return np.tanh(k * x) ** n

def basis(x, kind, k):
    if kind == 'rat':
        return x ** 3 / (1 + k * x * x)
    if kind == 'rat5':
        return x ** 5 / (1 + k * x * x)
    if kind == 'exp':
        return x * -np.expm1(-k * x * x)
    if kind == 'tanh':
        return np.tanh(k * x) ** 3
    if kind == 'sin':
        return np.sin(k * x) ** 3
    if kind == 'poly':
        return x ** 3
    if kind == 'soft':
        return x ** 3 / (1 + k * abs(x))
    if kind == 'pow':
        return np.sign(x) * abs(x) ** k

def fitB(u, v, kind, k, mode):

    def fn(x, I):
        q = x[:, I]
        a = basis(q, kind, k)
        fs = [q, a]
        if mode in ('power', 'all'):
            fs.append(a * q * q)
        if mode == 'pair':
            fs.extend([(q[:, 0] * q[:, 1])[:, None], (q[:, 0] * q[:, 1])[:, None] * q])
        return bias(np.column_stack(fs))
    fits = []
    for (I, J) in [([0, 3], [0, 1]), ([1, 2], [2, 3])]:
        I = list(range(4)) if mode in ('wide', 'all') else I
        F = fn(u, I)
        C = ls(F, v[:, J])
        fits.append((I, C))
    return lambda x: np.column_stack([fn(x, I) @ C for (I, C) in fits])

def mapB(u, v, kind, mode):
    from scipy.optimize import minimize_scalar

    def obj(k):
        return np.mean((fitB(u, v, kind, k, mode)(u) - v) ** 2)
    opt = minimize_scalar(obj, bounds=(1.1, 7) if kind == 'pow' else (0.03, 3), method='bounded')
    return (fitB(u, v, kind, opt.x, mode), opt.x, np.sqrt(opt.fun))

def fit(u, v, name, kind, n0=3):
    from scipy.optimize import least_squares

    def design(x, p):
        (k, n) = p[:2]
        z = trans(x, k, n, name)
        add = []
        if kind in ('wide', 'cross', 'sat', 'poly', 'mix'):
            add = [x]
        if kind == 'cross':
            add += [x * np.roll(x, 1, axis=1)]
        if kind == 'sat':
            add += [np.tanh(p[2] * x)]
        if kind == 'poly':
            add += [x ** 3]
        if kind == 'mix':
            add = [np.tanh(p[2] * x)]
        return bias(np.column_stack([z] + add))

    def err(p):
        F = design(u, p)
        return (F @ ls(F, v) - v).ravel()
    r = least_squares(err, [0.8, n0, 1.1], bounds=([0.005, 1.02, 0.05], [25, 7, 15]), max_nfev=120)
    p = r.x
    C = ls(design(u, p), v)
    return (np.sqrt(np.mean(r.fun ** 2)), p, C, lambda x: design(x, p) @ C)
